// 1. Input Validation & Configuration Check
int rejected = 0;

// Null pointers check
if (ra_input.current_q_bi == NULL || ra_input.target_q_bi == NULL || 
    ra_input.body_rate_rad_s == NULL) {
    rejected = 1;
}

// Enable/Valid check (must be 0 or 1)
if (!rejected && (ra_input.enable != 0 && ra_input.enable != 1)) rejected = 1;
if (!rejected && (ra_input.valid != 0 && ra_input.valid != 1)) rejected = 1;

// Finite checks for body rate
if (!rejected && (!isfinite(ra_input.body_rate_rad_s->x) ||
    !isfinite(ra_input.body_rate_rad_s->y) || !isfinite(ra_input.body_rate_rad_s->z))) {
    rejected = 1;
}

// Quaternion normalization
adcs_quat_t q_curr_norm, q_target_norm;
if (!rejected) {
    if (adcs_quat_normalize(ra_input.current_q_bi, &q_curr_norm) != ADCS_OK) rejected = 1;
    if (adcs_quat_normalize(ra_input.target_q_bi, &q_target_norm) != ADCS_OK) rejected = 1;
}

// Configuration constraints validation
if (!rejected) {
    if (!(ra_config.hold_enter_rad >= 0.0 && 
          ra_config.hold_enter_rad < ra_config.hold_exit_rad &&
          ra_config.hold_exit_rad <= ra_config.fine_enter_rad &&
          ra_config.fine_enter_rad < ra_config.fine_exit_rad &&
          ra_config.fine_exit_rad <= ADCS_PI &&
          ra_config.hold_rate_rad_s >= 0.0 &&
          ra_config.hold_rate_rad_s < ra_config.hold_rate_exit_rad_s &&
          ra_config.hold_rate_exit_rad_s <= ra_config.rate_enter_rad_s &&
          ra_config.rate_enter_rad_s < ra_config.rate_exit_rad_s)) {
        rejected = 1;
    }
    if (ra_config.rate_samples < 1 || ra_config.rate_samples > 20) rejected = 1;
    if (ra_config.fine_samples < 1 || ra_config.fine_samples > 20) rejected = 1;
    if (ra_config.hold_samples < 1 || ra_config.hold_samples > 20) rejected = 1;
    if (ra_config.max_bad_samples < 1 || ra_config.max_bad_samples > 20) rejected = 1;

    if (!isfinite(ra_config.dt_s) || ra_config.dt_s <= 0.0) rejected = 1;
    if (!isfinite(ra_config.integral_limit_rad_s) || ra_config.integral_limit_rad_s <= 0.0) rejected = 1;
    if (!isfinite(ra_config.torque_limit_nm) || ra_config.torque_limit_nm <= 0.0) rejected = 1;
    if (!isfinite(ra_config.kp) || ra_config.kp < 0.0) rejected = 1;
    if (!isfinite(ra_config.kd) || ra_config.kd < 0.0) rejected = 1;
    if (!isfinite(ra_config.ki) || ra_config.ki < 0.0) rejected = 1;
}

// 2. Disable / OFF Mode Handling
if (ra_input.enable == 0) {
    ra_state.mode = RA_OFF;
    ra_state.transition_samples = 0;
    ra_state.bad_samples = 0;
    ra_state.integral_error_rad_s.x = 0.0;
    ra_state.integral_error_rad_s.y = 0.0;
    ra_state.integral_error_rad_s.z = 0.0;
    ra_output.mode = RA_OFF;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = 0;
    ra_output.saturation_mask = 0;
    return;
}

// 3. Fault Logic & Rejection Handling
if (rejected) {
    ra_state.bad_samples++;
    ra_state.transition_samples = 0;
    ra_state.integral_error_rad_s.x = 0.0;
    ra_state.integral_error_rad_s.y = 0.0;
    ra_state.integral_error_rad_s.z = 0.0;

    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
}

if (ra_state.mode == RA_FAULT) {
    ra_output.mode = RA_FAULT;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0;
    return;
}

// Reset bad samples on accepted cycle
if (!rejected) {
    ra_state.bad_samples = 0;
}

// 4. Attitude Error Calculation
adcs_quat_t q_curr_conj = adcs_quat_conjugate(&q_curr_norm);
adcs_quat_t q_rel = adcs_quat_multiply(&q_target_norm, &q_curr_conj);

if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

double angle = 2.0 * acos(q_rel.w);
adcs_vec3_t e = {0, 0, 0};
if (angle > 1e-12) {
    double sin_half = sin(angle / 2.0);
    if (fabs(sin_half) > 1e-12) {
        double scale = angle / sin_half;
        e.x = q_rel.x * scale;
        e.y = q_rel.y * scale;
        e.z = q_rel.z * scale;
    }
}

double error_angle_rad = adcs_vec3_norm(&e);
double rate_mag = adcs_vec3_norm(ra_input.body_rate_rad_s);

// 5. Mode Transitions
int in_coarse_window = (error_angle_rad <= ra_config.fine_enter_rad && rate_mag <= ra_config.rate_enter_rad_s);
int in_hold_window = (error_angle_rad <= ra_config.hold_enter_rad && rate_mag <= ra_config.hold_rate_rad_s);
int in_fine_hold_exit = (error_angle_rad >= ra_config.hold_exit_rad || rate_mag >= ra_config.hold_rate_exit_rad_s);

if (ra_state.mode == RA_OFF) {
    if (rate_mag > ra_config.rate_enter_rad_s) {
        ra_state.mode = RA_RATE_DAMP;
        ra_state.transition_samples = 0;
    } else {
        ra_state.mode = RA_COARSE;
        ra_state.transition_samples = 0;
    }
}
else if (ra_state.mode == RA_RATE_DAMP) {
    if (rate_mag >= ra_config.rate_exit_rad_s) {
        ra_state.transition_samples = 0;
    } else if (rate_mag <= ra_config.rate_enter_rad_s) {
        ra_state.transition_samples++;
        if (ra_state.transition_samples >= ra_config.rate_samples) {
            ra_state.mode = RA_COARSE;
            ra_state.transition_samples = 0;
        }
    } else {
        ra_state.transition_samples = 0;
    }
}
else if (ra_state.mode == RA_COARSE) {
    if (in_coarse_window) {
        ra_state.transition_samples++;
        if (ra_state.transition_samples >= ra_config.fine_samples) {
            ra_state.mode = RA_FINE;
            ra_state.transition_samples = 0;
        }
    } else {
        ra_state.transition_samples = 0;
    }
}
else if (ra_state.mode == RA_FINE) {
    if (error_angle_rad >= ra_config.fine_exit_rad || rate_mag >= ra_config.rate_exit_rad_s) {
        ra_state.mode = RA_COARSE;
        ra_state.integral_error_rad_s.x = 0.0;
        ra_state.integral_error_rad_s.y = 0.0;
        ra_state.integral_error_rad_s.z = 0.0;
        ra_state.transition_samples = 0;
    } else {
        if (in_hold_window) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.hold_samples) {
                ra_state.mode = RA_HOLD;
                ra_state.transition_samples = 0;
            }
        } else {
            ra_state.transition_samples = 0;
        }
    }
}
else if (ra_state.mode == RA_HOLD) {
    if (in_fine_hold_exit) {
        ra_state.mode = RA_FINE;
        ra_state.integral_error_rad_s.x = 0.0;
        ra_state.integral_error_rad_s.y = 0.0;
        ra_state.integral_error_rad_s.z = 0.0;
        ra_state.transition_samples = 0;
    }
}

// 6. Control Law
double kp_val = 0.0, kd_val = 0.0, ki_val = 0.0;
if (ra_state.mode == RA_RATE_DAMP) {
    kd_val = ra_config.kd;
} else if (ra_state.mode == RA_COARSE) {
    kp_val = ra_config.kp;
    kd_val = ra_config.kd;
} else { // FINE or HOLD
    kp_val = ra_config.kp;
    kd_val = ra_config.kd;
    ki_val = ra_config.ki;
}

adcs_vec3_t torque_unclamped = {0, 0, 0};
adcs_vec3_t torque_limited = {0, 0, 0};
unint32 sat_mask = 0;
adcs_vec3_t i_limited = ra_state.integral_error_rad_s;
int freeze_integral[3] = {0, 0, 0};

if (ra_state.mode == RA_FINE || ra_state.mode == RA_HOLD) {
    adcs_vec3_t i_proposed = {
        ra_state.integral_error_rad_s.x + e.x * ra_config.dt_s,
        ra_state.integral_error_rad_s.y + e.y * ra_config.dt_s,
        ra_state.integral_error_rad_s.z + e.z * ra_config.dt_s
    };

    i_limited.x = ADCS_CLAMP(i_proposed.x, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    i_limited.y = ADCS_CLAMP(i_proposed.y, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    i_limited.z = ADCS_CLAMP(i_proposed.z, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);

    adcs_vec3_t w = *ra_input.body_rate_rad_s;

    for (int i = 0; i < 3; i++) {
        double t_unclamped_i = -kp_val * e.v[i] - kd_val * w.v[i] - ki_val * i_limited.v[i];
        double t_limited_i;

        adcs_actuator_limit_t limit = {
            .min_value = -ra_config.torque_limit_nm,
            .max_value = ra_config.torque_limit_nm,
            .max_slew_per_s = 0.0
        };
        adcs_limit_scalar(t_unclamped_i, &limit, &t_limited_i);

        if (fabs(t_unclamped_i) > fabs(t_limited_i) + 1e-9) {
            sat_mask |= (1U << i);
            double t_pd_i = -kp_val * e.v[i] - kd_val * w.v[i];
            if (fabs(t_unclamped_i) > fabs(t_pd_i)) {
                freeze_integral[i] = 1;
            }
        }

        torque_unclamped.v[i] = t_unclamped_i;
        torque_limited.v[i] = t_limited_i;
    }

    if (freeze_integral[0]) i_limited.x = ra_state.integral_error_rad_s.x;
    if (freeze_integral[1]) i_limited.y = ra_state.integral_error_rad_s.y;
    if (freeze_integral[2]) i_limited.z = ra_state.integral_error_rad_s.z;

    ra_state.integral_error_rad_s = i_limited;
}

ra_output.torque_nm = torque_limited;
ra_output.saturation_mask = sat_mask;
ra_output.error_angle_rad = error_angle_rad;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.mode = ra_state.mode;
ra_output.bad_samples = ra_state.bad_samples;

