        adcs_limit_scalar(t_unclamped_z, &limit_z, &t_limited_z);

        if (fabs(t_unclamped_z) > fabs(t_limited_z) + 1e-9) {
            sat_mask |= (1U << 2);
            double t_pd_z = -kp_val * e.z - kd_val * w.z;
            if (fabs(t_unclamped_z) > fabs(t_pd_z)) {
                freeze_integral[2] = 1;
            }
        }
        torque_unclamped.z = t_unclamped_z;
        torque_limited.z = t_limited_z;
    }

    if (freeze_integral[0]) i_limited.x = ra_state.integral_error_rad_s.x;
    if (freeze_integral[1]) i_limited.y = ra_state.integral_error_rad_s.y;
    if (freeze_integral[2]) i_limited.z = ra_state.integral_error_rad_s.z;

    ra_state.integral_error_rad_s = i_limited;
}

ra_output.torque_nm = torque_limited;
ra_output.saturation_mask = sat_mask;
ra_output.error_angle_rad = error_angle_rad;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.mode = ra_state.mode;
ra_output.bad_samples = ra_state.bad_samples;

candidates.misra:
// 1. Input Validation & Configuration Check
int rejected = 0;

// Null pointers check
if (ra_input.current_q_bi == NULL || ra_input.target_q_bi == NULL || 
    ra_input.body_rate_rad_s == NULL) {
    rejected = 1;
}

// Enable/Valid check (must be 0 or 1)
if (!rejected && (ra_input.enable != 0 && ra_input.enable != 1)) rejected = 1;
if (!rejected && (ra_input.valid != 0 && ra_input.valid != 1)) rejected = 1;

// Finite checks for body rate
if (!rejected && (!isfinite(ra_input.body_rate_rad_s->x) ||
    !isfinite(ra_input.body_rate_rad_s->y) || !isfinite(ra_input.body_rate_rad_s->z))) {
    rejected = 1;
}

// Quaternion normalization
adcs_quat_t q_curr_norm, q_target_norm;
if (!rejected) {
    if (adcs_quat_normalize(ra_input.current_q_bi, &q_curr_norm) != ADCS_OK) rejected = 1;
    if (adcs_quat_normalize(ra_input.target_q_bi, &q_target_norm) != ADCS_OK) rejected = 1;
}

// Configuration constraints validation
if (!rejected) {
    if (!(ra_config.hold_enter_rad >= 0.0 && 
          ra_config.hold_enter_rad < ra_config.hold_exit_rad &&
          ra_config.hold_exit_rad <= ra_config.fine_enter_rad &&
          ra_config.fine_enter_rad < ra_config.fine_exit_rad &&
          ra_config.fine_exit_rad <= ADCS_PI &&
          ra_config.hold_rate_rad_s >= 0.0 &&
          ra_config.hold_rate_rad_s < ra_config.hold_rate_exit_rad_s &&
          ra_config.hold_rate_exit_rad_s <= ra_config.rate_enter_rad_s &&
          ra_config.rate_enter_rad_s < ra_config.rate_exit_rad_s)) {
        rejected = 1;
    }
    if (ra_config.rate_samples < 1 || ra_config.rate_samples > 20) rejected = 1;
    if (ra_config.fine_samples < 1 || ra_config.fine_samples > 20) rejected = 1;
    if (ra_config.hold_samples < 1 || ra_config.hold_samples > 20) rejected = 1;
    if (ra_config.max_bad_samples < 1 || ra_config.max_bad_samples > 20) rejected = 1;

    if (!isfinite(ra_config.dt_s) || ra_config.dt_s <= 0.0) rejected = 1;
    if (!isfinite(ra_config.integral_limit_rad_s) || ra_config.integral_limit_rad_s <= 0.0) rejected = 1;
    if (!isfinite(ra_config.torque_limit_nm) || ra_config.torque_limit_nm <= 0.0) rejected = 1;
    if (!isfinite(ra_config.kp) || ra_config.kp < 0.0) rejected = 1;
    if (!isfinite(ra_config.kd) || ra_config.kd < 0.0) rejected = 1;
    if (!isfinite(ra_config.ki) || ra_config.ki < 0.0) rejected = 1;
}

// 2. Disable / OFF Mode Handling
if (ra_input.enable == 0) {
    ra_state.mode = RA_OFF;
    ra_state.transition_samples = 0U;
    ra_state.bad_samples = 0U;
    ra_state.integral_error_rad_s.x = 0.0;
    ra_state.integral_error_rad_s.y = 0.0;
    ra_state.integral_error_rad_s.z = 0.0;
    ra_output.mode = RA_OFF;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = 0U;
    ra_output.saturation_mask = 0U;
    return;
}

// 3. Fault Logic & Rejection Handling
if (rejected) {
    ra_state.bad_samples++;
    ra_state.transition_samples = 0U;
    ra_state.integral_error_rad_s.x = 0.0;
    ra_state.integral_error_rad_s.y = 0.0;
    ra_state.integral_error_rad_s.z = 0.0;

    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
}

if (ra_state.mode == RA_FAULT) {
    ra_output.mode = RA_FAULT;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0;
    return;
}

// Reset bad samples on accepted cycle
if (!rejected) {
    ra_state.bad_samples = 0;
}

// 4. Attitude Error Calculation
adcs_quat_t q_curr_conj = adcs_quat_conjugate(&q_curr_norm);
adcs_quat_t q_rel = adcs_quat_multiply(&q_target_norm, &q_curr_conj);

if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

double angle = 2.0 * acos(q_rel.w);
adcs_vec3_t e = {0, 0, 0};
if (angle > 1e-12) {
    double sin_half = sin(angle / 2.0);
    if (fabs(sin_half) > 1e-12) {
        double scale = angle / sin_half;
        e.x = q_rel.x * scale;
        e.y = q_rel.y * scale;
        e.z = q_rel.z * scale;
    }
}

double error_angle_rad = adcs_vec3_norm(&e);
double rate_mag = adcs_vec3_norm(ra_input.body_rate_rad_s);

// 5. Mode Transitions
int in_coarse_window = (error_angle_rad <= ra_config.fine_enter_rad && rate_mag <= ra_config.rate_enter_rad_s);
int in_hold_window = (error_angle_rad <= ra_config.hold_enter_rad && rate_mag <= ra_config.hold_rate_rad_s);
int in_fine_hold_exit = (error_angle_rad >= ra_config.hold_exit_rad || rate_mag >= ra_config.hold_rate_exit_rad_s);

if (ra_state.mode == RA_OFF) {
    if (rate_mag > ra_config.rate_enter_rad_s) {
        ra_state.mode = (ra_mode_t)RA_RATE_DAMP;
        ra_state.transition_samples = 0U;
    } else {
        ra_state.mode = (ra_mode_t)RA_COARSE;
        ra_state.transition_samples = 0U;
    }
}
else if (ra_state.mode == RA_RATE_DAMP) {
    if (rate_mag >= ra_config.rate_exit_rad_s) {
        ra_state.transition_samples = 0U;
    } else if (rate_mag <= ra_config.rate_enter_rad_s) {
        ra_state.transition_samples++;
        if (ra_state.transition_samples >= ra_config.rate_samples) {
            ra_state.mode = (ra_mode_t)RA_COARSE;
            ra_state.transition_samples = 0U;
        }
    } else {
        ra_state.transition_samples = 0U;
    }
}
else if (ra_state.mode == RA_COARSE) {
    if (in_coarse_window) {
        ra_state.transition_samples++;
        if (ra_state.transition_samples >= ra_config.fine_samples) {
            ra_state.mode = (ra_mode_t)RA_FINE;
            ra_state.transition_samples = 0U;
        }
    } else {
        ra_state.transition_samples = 0U;
    }
}
else if (ra_state.mode == RA_FINE) {
    if (error_angle_rad >= ra_config.fine_exit_rad || rate_mag >= ra_config.rate_exit_rad_s) {
        ra_state.mode = (ra_mode_t)RA_COARSE;
        ra_state.integral_error_rad_s.x = 0.0;
        ra_state.integral_error_rad_s.y = 0.0;
        ra_state.integral_error_rad_s.z = 0.0;
        ra_state.transition_samples = 0U;
    } else {
        if (in_hold_window) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.hold_samples) {
                ra_state.mode = (ra_mode_t)RA_HOLD;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
    }
}
else if (ra_state.mode == RA_HOLD) {
    if (in_fine_hold_exit) {
        ra_state.mode = (ra_mode_t)RA_FINE;
        ra_state.integral_error_rad_s.x = 0.0;
        ra_state.integral_error_rad_s.y = 0.0;
        ra_state.integral_error_rad_s.z = 0.0;
        ra_state.transition_samples = 0U;
    }
} else {
    /* Default case for MISRA 15.7 compliance */
}

// 6. Control Law
double kp_val = 0.0, kd_val = 0.0, ki_val = 0.0;
if (ra_state.mode == RA_RATE_DAMP) {
    kd_val = ra_config.kd;
} else if (ra_state.mode == RA_COARSE) {
    kp_val = ra_config.kp;
    kd_val = ra_config.kd;
} else { // FINE or HOLD
    kp_val = ra_config.kp;
    kd_val = ra_config.kd;
    ki_val = ra_config.ki;
}

adcs_vec3_t torque_unclamped = {0, 0, 0};
adcs_vec3_t torque_limited = {0, 0, 0};
uint32_t sat_mask = 0U;
adcs_vec3_t i_limited = ra_state.integral_error_rad_s;
int freeze_integral[3] = {0, 0, 0};

if (ra_state.mode == RA_FINE || ra_state.mode == RA_HOLD) {
    adcs_vec3_t i_proposed = {
        ra_state.integral_error_rad_s.x + e.x * ra_config.dt_s,
        ra_state.integral_error_rad_s.y + e.y * ra_config.dt_s,
        ra_state.integral_error_rad_s.z + e.z * ra_config.dt_s
    };

    i_limited.x = ADCS_CLAMP(i_proposed.x, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    i_limited.y = ADCS_CLAMP(i_proposed.y, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    i_limited.z = ADCS_CLAMP(i_proposed.z, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);

    adcs_vec3_t w = *ra_input.body_rate_rad_s;

    // Axis X
    {
        double t_unclamped_x = -kp_val * e.x - kd_val * w.x - ki_val * i_limited.x;
        double t_limited_x;
        adcs_actuator_limit_t limit_x = {
            .min_value = -ra_config.torque_limit_nm,
            .max_value = ra_config.torque_limit_nm,
            .max_slew_per_s = 0.0
        };
        (void)adcs_limit_scalar(t_unclamped_x, &limit_x, &t_limited_x);

        if (fabs(t_unclamped_x) > fabs(t_limited_x) + 1e-9) {
            sat_mask |= ((uint32_t)1U << 0);
            double t_pd_x = -kp_val * e.x - kd_val * w.x;
            if (fabs(t_unclamped_x) > fabs(t_pd_x)) {
                freeze_integral[0] = 1;
            }
        }
        torque_unclamped.x = t_unclamped_x;
        torque_limited.x = t_limited_x;
    }

    // Axis Y
    {
        double t_unclamped_y = -kp_val * e.y - kd_val * w.y - ki_val * i_limited.y;
        double t_limited_y;
        adcs_actuator_limit_t limit_y = {
            .min_value = -ra_config.torque_limit_nm,
            .max_value = ra_config.torque_limit_nm,
            .max_slew_per_s = 0.0
        };
        (void)adcs_limit_scalar(t_unclamped_y, &limit_y, &t_limited_y);

        if (fabs(t_unclamped_y) > fabs(t_limited_y) + 1e-9) {
            sat_mask |= ((uint32_t)1U << 1);
            double t_pd_y = -kp_val * e.y - kd_val * w.y;
            if (fabs(t_unclamped_y) > fabs(t_pd_y)) {
                freeze_integral[1] = 1;
            }
        }
        torque_unclamped.y = t_unclamped_y;
        torque_limited.y = t_limited_y;
    }

    // Axis Z
    {
        double t_unclamped_z = -kp_val * e.z - kd_val * w.z - ki_val * i_limited.z;
        double t_limited_z;
        adcs_actuator_limit_t limit_z = {
            .min_value = -ra_config.torque_limit_nm,
            .max_value = ra_config.torque_limit_nm,
            .max_slew_per_s = 0.0
        };
        (void)adcs_limit_scalar(t_unclamped_z, &limit_z, &t_limited_z);

        if (fabs(t_unclamped_z) > fabs(t_limited_z) + 1e-9) {
            sat_mask |= ((uint32_t)1U << 2);
            double t_pd_z = -kp_val * e.z - kd_val * w.z;
            if (fabs(t_unclamped_z) > fabs(t_pd_z)) {
                freeze_integral[2] = 1;
            }
        }
        torque_unclamped.z = t_unclamped_z;
        torque_limited.z = t_limited_z;
    }

    if (freeze_integral[0]) i_limited.x = ra_state.integral_error_rad_s.x;
    if (freeze_integral[1]) i_limited.y = ra_state.integral_error_rad_s.y;
    if (freeze_integral[2]) i_limited.z = ra_state.integral_error_rad_s.z;

    ra_state.integral_error_rad_s = i_limited;
}

ra_output.torque_nm = torque_limited;
ra_output.saturation_mask = sat_mask;
ra_output.error_angle_rad = error_angle_rad;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.mode = ra_state.mode;
ra_output.bad_samples = ra_state.bad_samples;

candidates.raw:
    // 1. 基础参数校验
    if (ra_input.enable != 0 && ra_input.enable != 1) {
        goto reject_cycle;
    }
    if (ra_input.valid != 0 && ra_input.valid != 1) {
        goto reject_cycle;
    }
    if (ra_input.current_q_bi == NULL || ra_input.target_q_bi == NULL || ra_input.body_rate_rad_s == NULL) {
        goto reject_cycle;
    }
    if (!adcs_is_finite_vec3(ra_input.body_rate_rad_s)) {
        goto reject_cycle;
    }

    adcs_quat_t q_curr_norm, q_target_norm;
    if (adcs_quat_normalize(ra_input.current_q_bi, &q_curr_norm) != ADCS_OK) {
        goto reject_cycle;
    }
    if (adcs_quat_normalize(ra_input.target_q_bi, &q_target_norm) != ADCS_OK) {
        goto reject_cycle;
    }

    // 2. OFF模式处理
    if (ra_input.enable == 0) {
        ra_state.mode = RA_OFF;
        ra_state.transition_samples = 0;
        ra_state.bad_samples = 0;
        ra_state.integral_error_rad_s.x = 0.0;
        ra_state.integral_error_rad_s.y = 0.0;
        ra_state.integral_error_rad_s.z = 0.0;
        ra_output.mode = RA_OFF;
        ra_output.error_angle_rad = 0.0;
        ra_output.rate_magnitude_rad_s = 0.0;
        ra_output.torque_nm.x = 0.0;
        ra_output.torque_nm.y = 0.0;
        ra_output.torque_nm.z = 0.0;
        ra_output.bad_samples = 0;
        ra_output.saturation_mask = 0U;
        return;
    }

    // 3. 配置校验
    int config_valid = 1;
    if (ra_config.hold_enter_rad < 0.0 || ra_config.hold_exit_rad <= ra_config.hold_enter_rad ||
        ra_config.fine_enter_rad <= ra_config.hold_exit_rad || ra_config.fine_exit_rad <= ra_config.fine_enter_rad ||
        ra_config.fine_exit_rad > ADCS_PI ||
        ra_config.hold_rate_rad_s < 0.0 || ra_config.hold_rate_exit_rad_s <= ra_config.hold_rate_rad_s ||
        ra_config.rate_enter_rad_s <= ra_config.hold_rate_exit_rad_s || ra_config.rate_exit_rad_s <= ra_config.rate_enter_rad_s ||
        ra_config.max_bad_samples < 1 || ra_config.max_bad_samples > 20 ||
        ra_config.dt_s <= 0.0 || !isfinite(ra_config.dt_s) ||
        ra_config.integral_limit_rad_s <= 0.0 || !isfinite(ra_config.integral_limit_rad_s) ||
        ra_config.torque_limit_nm <= 0.0 || !isfinite(ra_config.torque_limit_nm) ||
        ra_config.kp < 0.0 || !isfinite(ra_config.kp) ||
        ra_config.kd < 0.0 || !isfinite(ra_config.kd) ||
        ra_config.ki < 0.0 || !isfinite(ra_config.ki)) {
        config_valid = 0;
    }

    if (!config_valid) {
        goto reject_cycle;
    }

    // 4. 计算误差和速率
    adcs_quat_t q_err_raw = adcs_quat_multiply(&q_target_norm, &adcs_quat_conjugate(&q_curr_norm));
    // 选择最短路径: 如果实部小于0，取反
    if (q_err_raw.w < 0.0) {
        q_err_raw.w = -q_err_raw.w;
        q_err_raw.x = -q_err_raw.x;
        q_err_raw.y = -q_err_raw.y;
        q_err_raw.z = -q_err_raw.z;
    }

    double angle_rad = 2.0 * acos(q_err_raw.w);
    if (angle_rad > ADCS_PI) angle_rad = ADCS_TWO_PI - angle_rad;

    adcs_vec3_t e_vec;
    if (angle_rad < 1e-12) {
        e_vec = (adcs_vec3_t){0, 0, 0};
    } else {
        double sin_half = sqrt(1.0 - q_err_raw.w * q_err_raw.w);
        if (sin_half < 1e-12) sin_half = 1e-12;
        double scale = angle_rad / sin_half;
        e_vec.x = q_err_raw.x * scale;
        e_vec.y = q_err_raw.y * scale;
        e_vec.z = q_err_raw.z * scale;
    }

    double rate_mag = adcs_vec3_norm(ra_input.body_rate_rad_s);

    // 5. 模式转换逻辑
    ra_mode_t next_mode = ra_state.mode;
    unint32 trans_cnt = ra_state.transition_samples;

    switch (ra_state.mode) {
        case RA_OFF:
            if (rate_mag > ra_config.rate_enter_rad_s) {
                next_mode = RA_RATE_DAMP;
            } else {
                next_mode = RA_COARSE;
            }
            trans_cnt = 0;
            break;

        case RA_RATE_DAMP:
            if (rate_mag >= ra_config.rate_exit_rad_s) {
                trans_cnt = 0;
            } else if (rate_mag <= ra_config.rate_enter_rad_s) {
                trans_cnt++;
                if (trans_cnt >= ra_config.rate_samples) {
                    next_mode = RA_COARSE;
                    trans_cnt = 0;
                }
            } else {
                trans_cnt = 0;
            }
            break;

        case RA_COARSE:
            if ((angle_rad <= ra_config.fine_enter_rad) && (rate_mag <= ra_config.rate_enter_rad_s)) {
                trans_cnt++;
                if (trans_cnt >= ra_config.fine_samples) {
                    next_mode = RA_FINE;
                    trans_cnt = 0;
                }
            } else {
                trans_cnt = 0;
            }
            break;

        case RA_FINE:
            if ((angle_rad >= ra_config.fine_exit_rad) || (rate_mag >= ra_config.rate_exit_rad_s)) {
                next_mode = RA_COARSE;
                trans_cnt = 0;
                ra_state.integral_error_rad_s.x = 0.0;
                ra_state.integral_error_rad_s.y = 0.0;
                ra_state.integral_error_rad_s.z = 0.0;
            } else {
                if ((angle_rad <= ra_config.hold_enter_rad) && (rate_mag <= ra_config.hold_rate_rad_s)) {
                    trans_cnt++;
                    if (trans_cnt >= ra_config.hold_samples) {
                        next_mode = RA_HOLD;
                        trans_cnt = 0;
                    }
                } else {
                    trans_cnt = 0;
                }
            }
            break;

        case RA_HOLD:
            if ((angle_rad >= ra_config.hold_exit_rad) || (rate_mag >= ra_config.hold_rate_exit_rad_s)) {
                next_mode = RA_FINE;
                trans_cnt = 0;
            }
            break;

        case RA_FAULT:
            next_mode = RA_FAULT;
            trans_cnt = 0;
            break;

        default:
            next_mode = RA_OFF;
            break;
    }

    ra_state.mode = next_mode;
    ra_state.transition_samples = trans_cnt;

    // 6. 控制律计算
    int is_pid = (next_mode == RA_FINE) || (next_mode == RA_HOLD);
    double kp_eff = (next_mode == RA_RATE_DAMP) ? 0.0 : ra_config.kp;
    double kd_eff = ra_config.kd;
    double ki_eff = (is_pid) ? ra_config.ki : 0.0;

    // Save previous integral for potential rollback
    adcs_vec3_t prev_int = ra_state.integral_error_rad_s;

    if (is_pid) {
        adcs_vec3_t prop_int;
        prop_int.x = ra_state.integral_error_rad_s.x + e_vec.x * ra_config.dt_s;
        prop_int.y = ra_state.integral_error_rad_s.y + e_vec.y * ra_config.dt_s;
        prop_int.z = ra_state.integral_error_rad_s.z + e_vec.z * ra_config.dt_s;

        double lim = ra_config.integral_limit_rad_s;
        prop_int.x = ADCS_CLAMP(prop_int.x, -lim, lim);
        prop_int.y = ADCS_CLAMP(prop_int.y, -lim, lim);
        prop_int.z = ADCS_CLAMP(prop_int.z, -lim, lim);

        // Calculate unlimited torque with new integral
        double t_unlim_x_new = -kp_eff * e_vec.x - kd_eff * ra_input.body_rate_rad_s->x - ki_eff * prop_int.x;
        double t_unlim_y_new = -kp_eff * e_vec.y - kd_eff * ra_input.body_rate_rad_s->y - ki_eff * prop_int.y;
        double t_unlim_z_new = -kp_eff * e_vec.z - kd_eff * ra_input.body_rate_rad_s->z - ki_eff * prop_int.z;

        // Check saturation and freeze logic
        // Determine if axes were previously saturated? 
        // The requirement says "drive an already-saturated torque farther into saturation".
        // We approximate "already-saturated" as the axis being at its limit in the UNLIMITED calculation relative to the limit.
        // If the new unlimited torque is further out of bounds than the old one (or just out of bounds), freeze.
        // Simpler: If the axis is saturated (unlimited > limit), check if the integral change increases the magnitude beyond limit.

        adcs_vec3_t final_int = prop_int;

        // Helper lambda-like logic for each axis
        #define CHECK_FREEZE(axis, unlim_old, unlim_new, limit_val) \
            do { \
                double diff_old = unlim_old - limit_val; \
