                    if (trans_cnt >= ra_config.hold_samples) {
                        next_mode = RA_HOLD;
                        trans_cnt = 0;
                    }
                } else {
                    trans_cnt = 0;
                }
            }
            break;

        case RA_HOLD:
            if ((angle_rad >= ra_config.hold_exit_rad) || (rate_mag >= ra_config.hold_rate_exit_rad_s)) {
                next_mode = RA_FINE;
                trans_cnt = 0;
            }
            break;

        case RA_FAULT:
            next_mode = RA_FAULT;
            trans_cnt = 0;
            break;

        default:
            next_mode = RA_OFF;
            break;
    }

    ra_state.mode = next_mode;
    ra_state.transition_samples = trans_cnt;

    // 6. 控制律计算
    int is_pid = (next_mode == RA_FINE) || (next_mode == RA_HOLD);
    double kp_eff = (next_mode == RA_RATE_DAMP) ? 0.0 : ra_config.kp;
    double kd_eff = ra_config.kd;
    double ki_eff = (is_pid) ? ra_config.ki : 0.0;

    // Save previous integral for potential rollback
    adcs_vec3_t prev_int = ra_state.integral_error_rad_s;

    if (is_pid) {
        adcs_vec3_t prop_int;
        prop_int.x = ra_state.integral_error_rad_s.x + e_vec.x * ra_config.dt_s;
        prop_int.y = ra_state.integral_error_rad_s.y + e_vec.y * ra_config.dt_s;
        prop_int.z = ra_state.integral_error_rad_s.z + e_vec.z * ra_config.dt_s;

        double lim = ra_config.integral_limit_rad_s;
        prop_int.x = ADCS_CLAMP(prop_int.x, -lim, lim);
        prop_int.y = ADCS_CLAMP(prop_int.y, -lim, lim);
        prop_int.z = ADCS_CLAMP(prop_int.z, -lim, lim);

        // Calculate unlimited torque with new integral
        double t_unlim_x_new = -kp_eff * e_vec.x - kd_eff * ra_input.body_rate_rad_s->x - ki_eff * prop_int.x;
        double t_unlim_y_new = -kp_eff * e_vec.y - kd_eff * ra_input.body_rate_rad_s->y - ki_eff * prop_int.y;
        double t_unlim_z_new = -kp_eff * e_vec.z - kd_eff * ra_input.body_rate_rad_s->z - ki_eff * prop_int.z;

        // Check saturation and freeze logic
        // Determine if axes were previously saturated? 
        // The requirement says "drive an already-saturated torque farther into saturation".
        // We approximate "already-saturated" as the axis being at its limit in the UNLIMITED calculation relative to the limit.
        // If the new unlimited torque is further out of bounds than the old one (or just out of bounds), freeze.
        // Simpler: If the axis is saturated (unlimited > limit), check if the integral change increases the magnitude beyond limit.

        adcs_vec3_t final_int = prop_int;

        // Helper lambda-like logic for each axis
        #define CHECK_FREEZE(axis, unlim_old, unlim_new, limit_val) \
            do { \
                double diff_old = unlim_old - limit_val; \
                double diff_new = unlim_new - limit_val; \
                if (diff_old > 0 && diff_new > diff_old) { \
                    final_int.axis = prev_int.axis; \
                } \
                diff_old = -unlim_old - limit_val; /* lower bound check */ \
                diff_new = -unlim_new - limit_val; \
                if (diff_old > 0 && diff_new > diff_old) { \
                    final_int.axis = prev_int.axis; \
                } \
            } while(0)

        // Recalculate unlimited torques with OLD integral for comparison
        double t_unlim_x_old = -kp_eff * e_vec.x - kd_eff * ra_input.body_rate_rad_s->x - ki_eff * prev_int.x;
        double t_unlim_y_old = -kp_eff * e_vec.y - kd_eff * ra_input.body_rate_rad_s->y - ki_eff * prev_int.y;
        double t_unlim_z_old = -kp_eff * e_vec.z - kd_eff * ra_input.body_rate_rad_s->z - ki_eff * prev_int.z;

        CHECK_FREEZE(x, t_unlim_x_old, t_unlim_x_new, ra_config.torque_limit_nm);
        CHECK_FREEZE(y, t_unlim_y_old, t_unlim_y_new, ra_config.torque_limit_nm);
        CHECK_FREEZE(z, t_unlim_z_old, t_unlim_z_new, ra_config.torque_limit_nm);

        ra_state.integral_error_rad_s = final_int;
    } else {
        if (ra_state.mode != RA_FINE && ra_state.mode != RA_HOLD) {
             ra_state.integral_error_rad_s.x = 0.0;
             ra_state.integral_error_rad_s.y = 0.0;
             ra_state.integral_error_rad_s.z = 0.0;
        }
    }

    // Calculate final Unlimited Torque with finalized integral
    double t_unlim_x = -kp_eff * e_vec.x - kd_eff * ra_input.body_rate_rad_s->x - ki_eff * ra_state.integral_error_rad_s.x;
    double t_unlim_y = -kp_eff * e_vec.y - kd_eff * ra_input.body_rate_rad_s->y - ki_eff * ra_state.integral_error_rad_s.y;
    double t_unlim_z = -kp_eff * e_vec.z - kd_eff * ra_input.body_rate_rad_s->z - ki_eff * ra_state.integral_error_rad_s.z;

    adcs_actuator_limit_t limit;
    limit.min_value = -ra_config.torque_limit_nm;
    limit.max_value = ra_config.torque_limit_nm;

    double t_limited_x, t_limited_y, t_limited_z;
    adcs_limit_scalar(t_unlim_x, &limit, &t_limited_x);
    adcs_limit_scalar(t_unlim_y, &limit, &t_limited_y);
    adcs_limit_scalar(t_unlim_z, &limit, &t_limited_z);

    uint32_t sat_mask = 0;
    if (fabs(t_unlim_x) > ra_config.torque_limit_nm) sat_mask |= 1;
    if (fabs(t_unlim_y) > ra_config.torque_limit_nm) sat_mask |= 2;
    if (fabs(t_unlim_z) > ra_config.torque_limit_nm) sat_mask |= 4;

    ra_output.mode = next_mode;
    ra_output.error_angle_rad = angle_rad;
    ra_output.rate_magnitude_rad_s = rate_mag;
    ra_output.torque_nm.x = t_limited_x;
    ra_output.torque_nm.y = t_limited_y;
    ra_output.torque_nm.z = t_limited_z;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = sat_mask;

    return;

reject_cycle:
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    ra_state.integral_error_rad_s.x = 0.0;
    ra_state.integral_error_rad_s.y = 0.0;
    ra_state.integral_error_rad_s.z = 0.0;
    ra_state.transition_samples = 0;

candidates.raw:
// 1. Input Validation
if (ra_input.enable != 0 && ra_input.enable != 1) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}
if (ra_input.valid != 0 && ra_input.valid != 1) {
