if (!isfinite(ra_input.body_rate_rad_s->x) || !isfinite(ra_input.body_rate_rad_s->y) || !isfinite(ra_input.body_rate_rad_s->z)) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

adcs_quat_t q_curr_norm, q_target_norm;
if (adcs_quat_normalize(ra_input.current_q_bi, &q_curr_norm) != ADCS_OK) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}
if (adcs_quat_normalize(ra_input.target_q_bi, &q_target_norm) != ADCS_OK) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

// 2. Handle Disable/OFF
if (ra_input.enable == 0) {
    ra_state.mode = RA_OFF;
    ra_state.transition_samples = 0;
    ra_state.bad_samples = 0;
    ra_state.integral_error_rad_s.x = 0.0;
    ra_state.integral_error_rad_s.y = 0.0;
    ra_state.integral_error_rad_s.z = 0.0;

    ra_output.mode = RA_OFF;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = adcs_vec3_norm(ra_input.body_rate_rad_s);
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

// 3. Calculate Error Quaternion and Rotation Vector
adcs_quat_t q_err_raw = adcs_quat_multiply(&q_target_norm, &adcs_quat_conjugate(&q_curr_norm));
if (q_err_raw.w < 0.0) {
    q_err_raw.w = -q_err_raw.w;
    q_err_raw.x = -q_err_raw.x;
    q_err_raw.y = -q_err_raw.y;
    q_err_raw.z = -q_err_raw.z;
}

double angle = 2.0 * acos(q_err_raw.w);
double sin_half_angle = sin(angle / 2.0);
adcs_vec3_t e = {0.0, 0.0, 0.0};
if (sin_half_angle > ADCS_EPS_NORM) {
    double scale = angle / sin_half_angle;
    e.x = q_err_raw.x * scale;
    e.y = q_err_raw.y * scale;
    e.z = q_err_raw.z * scale;
} else {
    e.x = 2.0 * q_err_raw.x;
    e.y = 2.0 * q_err_raw.y;
    e.z = 2.0 * q_err_raw.z;
}

double rate_mag = adcs_vec3_norm(ra_input.body_rate_rad_s);
double angle_rad = angle;

// 4. Mode Transitions
int in_coarse_window = (angle_rad <= ra_config.fine_enter_rad && rate_mag <= ra_config.rate_enter_rad_s);
int in_fine_hold_window = (angle_rad <= ra_config.hold_enter_rad && rate_mag <= ra_config.hold_rate_rad_s);

switch (ra_state.mode) {
    case RA_OFF:
        if (rate_mag > ra_config.rate_enter_rad_s) {
            ra_state.mode = RA_RATE_DAMP;
            ra_state.transition_samples = 0;
        } else {
            ra_state.mode = RA_COARSE;
            ra_state.transition_samples = 0;
        }
        break;
    case RA_RATE_DAMP:
        if (rate_mag <= ra_config.rate_enter_rad_s) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.rate_samples) {
                ra_state.mode = RA_COARSE;
                ra_state.transition_samples = 0;
            }
        } else {
            ra_state.transition_samples = 0;
        }
        break;
    case RA_COARSE:
        if (in_coarse_window) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.fine_samples) {
                ra_state.mode = RA_FINE;
                ra_state.transition_samples = 0;
            }
        } else {
            ra_state.transition_samples = 0;
        }
        break;
    case RA_FINE:
        if (angle_rad >= ra_config.fine_exit_rad || rate_mag >= ra_config.rate_exit_rad_s) {
            ra_state.mode = RA_COARSE;
            ra_state.transition_samples = 0;
            ra_state.integral_error_rad_s.x = 0.0;
            ra_state.integral_error_rad_s.y = 0.0;
            ra_state.integral_error_rad_s.z = 0.0;
        } else {
            if (in_fine_hold_window) {
                ra_state.transition_samples++;
                if (ra_state.transition_samples >= ra_config.hold_samples) {
                    ra_state.mode = RA_HOLD;
                    ra_state.transition_samples = 0;
                }
            } else {
                ra_state.transition_samples = 0;
            }
        }
        break;
    case RA_HOLD:
        if (angle_rad >= ra_config.hold_exit_rad || rate_mag >= ra_config.hold_rate_exit_rad_s) {
            ra_state.mode = RA_FINE;
            ra_state.transition_samples = 0;
        }
        break;
    case RA_FAULT:
        ra_output.mode = RA_FAULT;
        ra_output.error_angle_rad = angle_rad;
        ra_output.rate_magnitude_rad_s = rate_mag;
        ra_output.torque_nm.x = 0.0;
        ra_output.torque_nm.y = 0.0;
        ra_output.torque_nm.z = 0.0;
        ra_output.bad_samples = ra_state.bad_samples;
        ra_output.saturation_mask = 0U;
        return;
}

// 5. Control Law Calculation
adcs_vec3_t torque_unlimited = {0.0, 0.0, 0.0};
double kp = (ra_state.mode == RA_RATE_DAMP) ? 0.0 : ra_config.kp;

if (ra_state.mode == RA_FINE || ra_state.mode == RA_HOLD) {
    adcs_vec3_t proposed_I = ra_state.integral_error_rad_s;
    proposed_I.x += e.x * ra_config.dt_s;
    proposed_I.y += e.y * ra_config.dt_s;
    proposed_I.z += e.z * ra_config.dt_s;

    proposed_I.x = ADCS_CLAMP(proposed_I.x, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    proposed_I.y = ADCS_CLAMP(proposed_I.y, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    proposed_I.z = ADCS_CLAMP(proposed_I.z, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);

    torque_unlimited.x = -kp * e.x - ra_config.kd * ra_input.body_rate_rad_s->x - ra_config.ki * proposed_I.x;
    torque_unlimited.y = -kp * e.y - ra_config.kd * ra_input.body_rate_rad_s->y - ra_config.ki * proposed_I.y;
    torque_unlimited.z = -kp * e.z - ra_config.kd * ra_input.body_rate_rad_s->z - ra_config.ki * proposed_I.z;

    adcs_actuator_limit_t limit = {
        .min_value = -ra_config.torque_limit_nm,
        .max_value = ra_config.torque_limit_nm,
        .max_slew_per_s = 0.0
    };

    unint32 sat_mask = 0U;
    double limited_torque[3];
    int sat_flag[3] = {0, 0, 0};

    for (int i = 0; i < 3; i++) {
        double val = (i == 0) ? torque_unlimited.x : ((i == 1) ? torque_unlimited.y : torque_unlimited.z);
        adcs_limit_scalar(val, &limit, &limited_torque[i]);
        if (fabs(limited_torque[i]) >= ra_config.torque_limit_nm) {
            sat_flag[i] = 1;
            sat_mask |= (unint32)(1U << i);
        }
    }

    adcs_vec3_t final_torque = {0.0, 0.0, 0.0};
    adcs_vec3_t effective_I = {0.0, 0.0, 0.0};

    for (int i = 0; i < 3; i++) {
        double ei = (i == 0) ? ra_state.integral_error_rad_s.x : ((i == 1) ? ra_state.integral_error_rad_s.y : ra_state.integral_error_rad_s.z);
        double pi_val = (i == 0) ? proposed_I.x : ((i == 1) ? proposed_I.y : proposed_I.z);

        if (sat_flag[i]) {
            if (i==0) effective_I.x = ei;
            if (i==1) effective_I.y = ei;
            if (i==2) effective_I.z = ei;

            double frozen_torque_val = -kp * (i==0?e.x:(i==1?e.y:e.z)) - ra_config.kd * (i==0?ra_input.body_rate_rad_s->x:(i==1?ra_input.body_rate_rad_s->y:ra_input.body_rate_rad_s->z)) - ra_config.ki * ei;
            double frozen_limited;
            adcs_limit_scalar(frozen_torque_val, &limit, &frozen_limited);

            if (i==0) final_torque.x = frozen_limited;
            if (i==1) final_torque.y = frozen_limited;
            if (i==2) final_torque.z = frozen_limited;
        } else {
            if (i==0) effective_I.x = pi_val;
            if (i==1) effective_I.y = pi_val;
            if (i==2) effective_I.z = pi_val;

            if (i==0) final_torque.x = limited_torque[0];
            if (i==1) final_torque.y = limited_torque[1];
            if (i==2) final_torque.z = limited_torque[2];
        }
    }

    ra_state.integral_error_rad_s = effective_I;
    ra_output.torque_nm = final_torque;
    ra_output.saturation_mask = sat_mask;

} else {
    torque_unlimited.x = -kp * e.x - ra_config.kd * ra_input.body_rate_rad_s->x;
    torque_unlimited.y = -kp * e.y - ra_config.kd * ra_input.body_rate_rad_s->y;
    torque_unlimited.z = -kp * e.z - ra_config.kd * ra_input.body_rate_rad_s->z;

    adcs_actuator_limit_t limit = {
        .min_value = -ra_config.torque_limit_nm,
        .max_value = ra_config.torque_limit_nm,
        .max_slew_per_s = 0.0
    };

    unint32 sat_mask = 0U;
    double limited_torque[3];

    for (int i = 0; i < 3; i++) {
        double val = (i == 0) ? torque_unlimited.x : ((i == 1) ? torque_unlimited.y : torque_unlimited.z);
        adcs_limit_scalar(val, &limit, &limited_torque[i]);
        if (fabs(limited_torque[i]) >= ra_config.torque_limit_nm) {
            sat_mask |= (unint32)(1U << i);
        }
    }

    ra_output.torque_nm.x = limited_torque[0];
    ra_output.torque_nm.y = limited_torque[1];
    ra_output.torque_nm.z = limited_torque[2];
    ra_output.saturation_mask = sat_mask;
}

// 6. Output Assignment
ra_output.mode = ra_state.mode;
ra_output.error_angle_rad = angle_rad;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.bad_samples = ra_state.bad_samples;

ra_state.bad_samples = 0;

