    double limited_torque[3];
    int sat_flag[3] = {0, 0, 0};

    for (int i = 0; i < 3; i++) {
        double val = (i == 0) ? torque_unlimited.x : ((i == 1) ? torque_unlimited.y : torque_unlimited.z);
        (void)adcs_limit_scalar(val, &limit, &limited_torque[i]);
        if (fabs(limited_torque[i]) >= ra_config.torque_limit_nm) {
            sat_flag[i] = 1;
            sat_mask |= (uint32_t)(1U << i);
        }
    }

    adcs_vec3_t final_torque = {0.0, 0.0, 0.0};
    adcs_vec3_t effective_I = {0.0, 0.0, 0.0};

    for (int i = 0; i < 3; i++) {
        double ei = (i == 0) ? ra_state.integral_error_rad_s.x : ((i == 1) ? ra_state.integral_error_rad_s.y : ra_state.integral_error_rad_s.z);
        double pi_val = (i == 0) ? proposed_I.x : ((i == 1) ? proposed_I.y : proposed_I.z);

        if (sat_flag[i]) {
            if (i==0) effective_I.x = ei;
            if (i==1) effective_I.y = ei;
            if (i==2) effective_I.z = ei;

            double frozen_torque_val = -kp * (i==0?e.x:(i==1?e.y:e.z)) - ra_config.kd * (i==0?ra_input.body_rate_rad_s->x:(i==1?ra_input.body_rate_rad_s->y:ra_input.body_rate_rad_s->z)) - ra_config.ki * ei;
            double frozen_limited;
            adcs_limit_scalar(frozen_torque_val, &limit, &frozen_limited);

            if (i==0) final_torque.x = frozen_limited;
            if (i==1) final_torque.y = frozen_limited;
            if (i==2) final_torque.z = frozen_limited;
        } else {
            if (i==0) effective_I.x = pi_val;
            if (i==1) effective_I.y = pi_val;
            if (i==2) effective_I.z = pi_val;

            if (i==0) final_torque.x = limited_torque[0];
            if (i==1) final_torque.y = limited_torque[1];
            if (i==2) final_torque.z = limited_torque[2];
        }
    }

    ra_state.integral_error_rad_s = effective_I;
    ra_output.torque_nm = final_torque;
    ra_output.saturation_mask = sat_mask;

} else {
    torque_unlimited.x = -kp * e.x - ra_config.kd * ra_input.body_rate_rad_s->x;
    torque_unlimited.y = -kp * e.y - ra_config.kd * ra_input.body_rate_rad_s->y;
    torque_unlimited.z = -kp * e.z - ra_config.kd * ra_input.body_rate_rad_s->z;

    adcs_actuator_limit_t limit = {
        .min_value = -ra_config.torque_limit_nm,
        .max_value = ra_config.torque_limit_nm,
        .max_slew_per_s = 0.0
    };

    uint32_t sat_mask = 0U;
    double limited_torque[3];

    for (int i = 0; i < 3; i++) {
        double val = (i == 0) ? torque_unlimited.x : ((i == 1) ? torque_unlimited.y : torque_unlimited.z);
        (void)adcs_limit_scalar(val, &limit, &limited_torque[i]);
        if (fabs(limited_torque[i]) >= ra_config.torque_limit_nm) {
            sat_mask |= (uint32_t)(1U << i);
        }
    }

    ra_output.torque_nm.x = limited_torque[0];
    ra_output.torque_nm.y = limited_torque[1];
    ra_output.torque_nm.z = limited_torque[2];
    ra_output.saturation_mask = sat_mask;
}

// 6. Output Assignment
ra_output.mode = ra_state.mode;
ra_output.error_angle_rad = angle_rad;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.bad_samples = ra_state.bad_samples;

ra_state.bad_samples = 0;
